class SequentialCrawler {
    private final HtmlParser parser;
    SequentialCrawler(HtmlParser parser) { this.parser = parser; }

    public List<String> crawl(String startUrl) {
        String host = getHost(startUrl);
        Set<String> visited = new HashSet<>();
        Queue<String> queue = new ArrayDeque<>();
        visited.add(startUrl);
        queue.offer(startUrl);
        while (!queue.isEmpty()) {
            String url = queue.poll();
            for (String next : parser.getUrls(url)) {
                if (!getHost(next).equals(host)) continue;
                if (visited.add(next)) queue.offer(next);
            }
        }
        return new ArrayList<>(visited);
    }

    private String getHost(String url) {
        try { return new java.net.URI(url).getHost().toLowerCase(); }
        catch (Exception e) { return ""; }
    }
}

