import java.net.URI;
import java.util.*;
import java.util.concurrent.*;

interface HtmlParser {
    List<String> getUrls(String url);
}

public class WebCrawler {
    private final HtmlParser parser;
    private final ExecutorService executor;

    public WebCrawler(HtmlParser parser, int maxThreads) {
        this.parser = parser;
        this.executor = Executors.newFixedThreadPool(maxThreads);
    }

    public List<String> crawl(String startUrl) {
        String host = getHost(startUrl);
        Set<String> visited = ConcurrentHashMap.newKeySet();
        visited.add(startUrl);

        List<String> frontier = List.of(startUrl);

        while (!frontier.isEmpty()) {
            List<Future<List<String>>> futures = new ArrayList<>(frontier.size());
            for (String url : frontier) {
                futures.add(executor.submit(() -> safeFetch(url)));
            }
            List<String> nextFrontier = new ArrayList<>();
            for (Future<List<String>> f : futures) {
                List<String> links;
                try { links = f.get(); }
                catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                } catch (ExecutionException e) { continue; }
                for (String next : links) {
                    if (!getHost(next).equals(host)) continue; // filter before claim
                    if (visited.add(next)) nextFrontier.add(next); // atomic claim
                }
            }
            frontier = nextFrontier;
        }
        return new ArrayList<>(visited);
    }

    private List<String> safeFetch(String url) {
        try { return parser.getUrls(url); }
        catch (Exception e) { return List.of(); } // one bad page != failed crawl
    }

    private String getHost(String url) {
        try {
            String h = new URI(url).getHost();
            return h == null ? "" : h.toLowerCase();
        } catch (Exception e) { return ""; }
    }

    public void shutdown() { executor.shutdown(); }
}

from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import urlparse

def get_host(url: str) -> str:
    try:
        return (urlparse(url).hostname or "").lower()
    except Exception:
        return ""

def crawl(start_url: str, parser, max_threads: int = 8):
    host = get_host(start_url)
    visited = {start_url}
    frontier = [start_url]
    with ThreadPoolExecutor(max_workers=max_threads) as pool:
        while frontier:
            # One task per URL in the level: latency hiding without
            # sharing the queue across threads.
            future_to_url = {pool.submit(parser.get_urls, u): u for u in frontier}
            next_frontier = []
            for fut in as_completed(future_to_url):
                try:
                    links = fut.result() or []
                except Exception:
                    continue  # skip failed page, keep crawling
                for nxt in links:
                    if get_host(nxt) != host:
                        continue
                    if nxt not in visited:
                        visited.add(nxt)
                        next_frontier.append(nxt)
            frontier = next_frontier
    return list(visited)
